"""Board representation, parsing, rendering and validation.

A board is 81 digits, 0 meaning empty. We keep two views of it:

* the *string* form -- 81 characters, the interchange format used by every
  public sudoku dataset, and what the CLI accepts;
* the *array* form -- a ``numpy`` ``uint8`` array of shape ``(81,)``, which is
  what the solvers and (after encoding) the models consume.

Keeping the canonical form flat rather than 9x9 matters later: the models in
Stage 2 treat the grid as a sequence of 81 tokens, and reshaping to ``(9, 9)``
is a view, not a copy.
"""

from __future__ import annotations

import numpy as np

from .units import BOX, N, N_CELLS, UNITS

EMPTY = 0
#: Characters that a parser should treat as "no digit here".
BLANK_CHARS = frozenset({"0", ".", "_", "*"})
#: Characters that are grid decoration, not cells. Note ``-`` is layout, not a
#: blank: :func:`render` draws separator rules with it, and we want a rendered
#: grid to survive a round trip back through :func:`from_string`.
LAYOUT_CHARS = frozenset({"|", "+", "-"})


class BoardError(ValueError):
    """Raised when input cannot be parsed as a board."""


def from_string(text: str) -> np.ndarray:
    """Parse 81 characters into a ``uint8`` array of shape ``(81,)``.

    Accepts any of :data:`BLANK_CHARS` for an empty cell, and ignores
    newlines and pipes so that a pretty-printed grid can be pasted back in.
    """
    cleaned = [
        ch for ch in text if not ch.isspace() and ch not in LAYOUT_CHARS
    ]
    digits = []
    for ch in cleaned:
        if ch in BLANK_CHARS:
            digits.append(EMPTY)
        elif ch.isdigit():
            digits.append(int(ch))
        else:
            raise BoardError(f"unexpected character {ch!r} in board string")
    if len(digits) != N_CELLS:
        raise BoardError(f"expected {N_CELLS} cells, got {len(digits)}")
    return np.array(digits, dtype=np.uint8)


def to_string(board: np.ndarray) -> str:
    """Render a board back to its 81-character interchange form."""
    return "".join(str(int(v)) for v in board)


def render(board: np.ndarray, blank: str = ".") -> str:
    """Render a board as a human-readable grid with box separators."""
    lines = []
    for r in range(N):
        if r and r % BOX == 0:
            lines.append("------+-------+------")
        cells = []
        for c in range(N):
            if c and c % BOX == 0:
                cells.append("|")
            value = int(board[r * N + c])
            cells.append(blank if value == EMPTY else str(value))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def is_complete(board: np.ndarray) -> bool:
    """True if every cell is filled (says nothing about correctness)."""
    return not bool((board == EMPTY).any())


def find_conflicts(board: np.ndarray) -> list[tuple[int, int]]:
    """Return every pair of cells that share a unit and hold the same digit.

    An empty list means the board is *consistent* -- it breaks no constraint.
    A consistent board may still be incomplete, and an incomplete consistent
    board may still be unsolvable, which is exactly why Lesson 03 exists.
    """
    conflicts: set[tuple[int, int]] = set()
    for unit in UNITS:
        seen: dict[int, int] = {}
        for cell in unit:
            value = int(board[cell])
            if value == EMPTY:
                continue
            if value in seen:
                conflicts.add((min(seen[value], cell), max(seen[value], cell)))
            else:
                seen[value] = cell
    return sorted(conflicts)


def is_consistent(board: np.ndarray) -> bool:
    """True if the board breaks no constraint (it may still be incomplete)."""
    return not find_conflicts(board)


def is_solved(board: np.ndarray) -> bool:
    """True only if the board is both complete and consistent."""
    return is_complete(board) and is_consistent(board)


def clue_count(board: np.ndarray) -> int:
    """Number of filled cells. The crudest difficulty proxy there is."""
    return int((board != EMPTY).sum())


def to_grid(board: np.ndarray) -> np.ndarray:
    """Return a ``(9, 9)`` *view* of the flat board -- no copy is made."""
    return board.reshape(N, N)

"""Constraint propagation over candidate sets.

Every cell holds a *domain*: the set of digits it could still take. We store a
domain as a 9-bit integer, bit ``d - 1`` meaning "digit ``d`` is still possible".
Bitmasks make the inner loop branch-free and cheap:

    intersection   a & b
    removal        a & ~bit(d)
    "is singleton" mask.bit_count() == 1

Three inference rules live here, in increasing strength:

1. **Naked single** -- a cell with one candidate left must take it.
2. **Arc consistency (AC-3)** -- the textbook algorithm, run over the binary
   decomposition of the all-different constraints. On sudoku this turns out to
   be *exactly as strong as* naked singles, and Lesson 04 asks you to work out
   why. (Briefly: a binary ``!=`` arc can only prune when the other end is
   already a singleton.)
3. **Hidden single** -- if a digit has only one possible home left inside a
   unit, it goes there, even if that cell has several candidates. This reasons
   about the all-different constraint *as a whole*, so it is strictly stronger
   than arc consistency on the decomposition.

That gap between (2) and (3) is the whole reason "just run AC-3" does not solve
hard puzzles, and it is worth understanding before Stage 2 asks a neural network
to learn the same inferences.
"""

from __future__ import annotations

from .board import EMPTY
from .units import N, N_CELLS, PEERS, UNITS, UNITS_OF

#: All nine digits possible: 0b111111111.
FULL_MASK = (1 << N) - 1

Domains = list[int]


def bit(digit: int) -> int:
    """The single-bit mask for a digit 1..9."""
    return 1 << (digit - 1)


def mask_to_digits(mask: int) -> list[int]:
    """Expand a bitmask into the sorted list of digits it contains."""
    return [d for d in range(1, N + 1) if mask & bit(d)]


def only_digit(mask: int) -> int:
    """The digit in a singleton mask. Undefined for non-singletons."""
    return mask.bit_length()


def initial_domains(board) -> Domains | None:
    """Build starting domains from a board, pruning givens from their peers.

    Returns ``None`` if the board is already contradictory.
    """
    domains: Domains = [FULL_MASK] * N_CELLS
    for cell in range(N_CELLS):
        value = int(board[cell])
        if value == EMPTY:
            continue
        if not domains[cell] & bit(value):
            return None
        domains[cell] = bit(value)
        for peer in PEERS[cell]:
            domains[peer] &= ~bit(value)
            if domains[peer] == 0:
                return None
    return domains


def domains_to_board(domains: Domains, out) -> None:
    """Write every singleton domain back into ``out`` as a digit."""
    for cell in range(N_CELLS):
        mask = domains[cell]
        if mask.bit_count() == 1:
            out[cell] = only_digit(mask)


def naked_singles(domains: Domains) -> bool:
    """Propagate singleton domains to a fixpoint.

    Returns ``False`` on contradiction (some domain became empty).
    """
    queue = [c for c in range(N_CELLS) if domains[c].bit_count() == 1]
    while queue:
        cell = queue.pop()
        mask = domains[cell]
        if mask.bit_count() != 1:
            continue
        for peer in PEERS[cell]:
            if domains[peer] & mask:
                domains[peer] &= ~mask
                if domains[peer] == 0:
                    return False
                if domains[peer].bit_count() == 1:
                    queue.append(peer)
    return True


def hidden_singles(domains: Domains) -> bool:
    """Place digits that have exactly one possible cell within a unit.

    Returns ``False`` on contradiction (a digit with nowhere to go).
    """
    changed = True
    while changed:
        changed = False
        for unit in UNITS:
            for digit in range(1, N + 1):
                mask = bit(digit)
                homes = [cell for cell in unit if domains[cell] & mask]
                if not homes:
                    return False
                if len(homes) == 1:
                    cell = homes[0]
                    if domains[cell] != mask:
                        domains[cell] = mask
                        changed = True
                        if not naked_singles(domains):
                            return False
    return True


def revise(domains: Domains, xi: int, xj: int) -> bool:
    """AC-3's inner step: prune values of ``xi`` unsupported by ``xj``.

    For an all-different constraint the only unsupported value is ``xj``'s own
    value, and only when ``xj`` has just one candidate left.
    """
    if domains[xj].bit_count() != 1:
        return False
    if not domains[xi] & domains[xj]:
        return False
    domains[xi] &= ~domains[xj]
    return True


def ac3(domains: Domains) -> bool:
    """Textbook AC-3 over the binary decomposition of the sudoku constraints.

    Returns ``False`` if a domain is wiped out, ``True`` otherwise. Note that
    ``True`` does *not* mean solved -- see :func:`propagate`.
    """
    queue = [(xi, xj) for xj in range(N_CELLS) for xi in PEERS[xj]]
    while queue:
        xi, xj = queue.pop(0)
        if revise(domains, xi, xj):
            if domains[xi] == 0:
                return False
            queue.extend((xk, xi) for xk in PEERS[xi] if xk != xj)
    return True


def propagate(domains: Domains) -> bool:
    """Run naked singles and hidden singles together to a fixpoint.

    This is the propagator the search in :mod:`gridmind.solvers.backtracking`
    uses. Returns ``False`` on contradiction.
    """
    if not naked_singles(domains):
        return False
    return hidden_singles(domains)


def is_solved_domains(domains: Domains) -> bool:
    """True when every domain is a singleton."""
    return all(mask.bit_count() == 1 for mask in domains)


def unsolved_count(domains: Domains) -> int:
    """How many cells still have more than one candidate."""
    return sum(1 for mask in domains if mask.bit_count() > 1)

/** Board parsing, formatting and validation. Twin of `src/gridmind/board.py`. */

import { N, N_CELLS, UNITS } from "./units";

export const EMPTY = 0;

const BLANK_CHARS = new Set([".", "0", "_", "*"]);
const LAYOUT_CHARS = new Set(["|", "+", "-"]);

export type Board = Uint8Array;

export function fromString(text: string): Board {
  const digits: number[] = [];
  for (const ch of text) {
    if (/\s/.test(ch) || LAYOUT_CHARS.has(ch)) continue;
    if (BLANK_CHARS.has(ch)) digits.push(EMPTY);
    else if (ch >= "1" && ch <= "9") digits.push(Number(ch));
    else throw new Error(`unexpected character ${ch} in board string`);
  }
  if (digits.length !== N_CELLS) {
    throw new Error(`expected ${N_CELLS} cells, got ${digits.length}`);
  }
  return Uint8Array.from(digits);
}

export const toString_ = (board: Board): string => Array.from(board).join("");

export const isComplete = (board: Board): boolean =>
  !board.some((value) => value === EMPTY);

export function findConflicts(board: Board): Array<[number, number]> {
  const conflicts = new Set<string>();
  for (const unit of UNITS) {
    const seen = new Map<number, number>();
    for (const cell of unit) {
      const value = board[cell]!;
      if (value === EMPTY) continue;
      const previous = seen.get(value);
      if (previous !== undefined) {
        conflicts.add(`${Math.min(previous, cell)},${Math.max(previous, cell)}`);
      } else {
        seen.set(value, cell);
      }
    }
  }
  return [...conflicts].map((key) => {
    const [a, b] = key.split(",");
    return [Number(a), Number(b)] as [number, number];
  });
}

export const isConsistent = (board: Board): boolean =>
  findConflicts(board).length === 0;

export const isSolved = (board: Board): boolean =>
  isComplete(board) && isConsistent(board);

export const clueCount = (board: Board): number =>
  board.reduce((total, value) => total + (value === EMPTY ? 0 : 1), 0);

export function render(board: Board, blank = "."): string {
  const lines: string[] = [];
  for (let r = 0; r < N; r += 1) {
    if (r > 0 && r % 3 === 0) lines.push("------+-------+------");
    const cells: string[] = [];
    for (let c = 0; c < N; c += 1) {
      if (c > 0 && c % 3 === 0) cells.push("|");
      const value = board[r * N + c]!;
      cells.push(value === EMPTY ? blank : String(value));
    }
    lines.push(cells.join(" "));
  }
  return lines.join("\n");
}

/**
 * Scenario tests for the hint engine.
 *
 * These play whole games rather than checking single calls: follow hints to
 * completion, make deliberate mistakes, overwrite cells, erase, and assert the
 * invariants that matter. The engine gives advice a person will act on, so a
 * wrong hint is worse than no hint.
 *
 *   npm test
 */

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { EMPTY, fromString, isSolved, type Board } from "./board";
import { findDeadEnd, nextHint, type Edit } from "./hint";
import { countSolutions, solve } from "./solve";
import { PEERS } from "./units";

interface Puzzle {
  puzzle: string;
  solution: string;
  clues: number;
  nodes: number;
  label: string;
}

const PUZZLES: Puzzle[] = JSON.parse(
  readFileSync(new URL("../../public/puzzles.json", import.meta.url), "utf8"),
);

const REFERENCE = PUZZLES.find((p) => p.label === "Reference: hard")!;

/** A digit that is legal in `cell` right now but is not the answer. */
function wrongButLegal(board: Board, solution: Board, cell: number): number | null {
  const used = new Set(PEERS[cell]!.map((p) => board[p]!).filter((v) => v !== EMPTY));
  for (let d = 1; d <= 9; d += 1) {
    if (!used.has(d) && d !== solution[cell]) return d;
  }
  return null;
}

const firstEmpty = (board: Board): number => board.findIndex((v) => v === EMPTY);

// --- hints are never wrong --------------------------------------------------

test("following hints solves every puzzle, and never places a wrong digit", () => {
  for (const p of PUZZLES) {
    const solution = fromString(p.solution);
    const board = fromString(p.puzzle);

    for (let step = 0; step < 200; step += 1) {
      const hint = nextHint(board, solution);
      if (hint.kind === "solved") break;

      assert.ok(
        hint.kind === "deduction" || hint.kind === "refutation" || hint.kind === "reveal",
        `${p.label || p.puzzle.slice(0, 12)}: unexpected ${hint.kind} on a clean board`,
      );

      if (hint.kind === "deduction") {
        const { cell, digit } = hint.deduction;
        assert.equal(solution[cell], digit, `wrong deduction at ${cell}`);
        board[cell] = digit;
      } else if (hint.kind === "refutation") {
        for (const r of hint.refuted) {
          assert.notEqual(solution[hint.cell], r.digit, "refuted the correct digit");
        }
        board[hint.cell] = hint.determined ? hint.remaining[0]! : solution[hint.cell]!;
      } else {
        assert.equal(solution[hint.cell], hint.digit);
        board[hint.cell] = hint.digit;
      }
    }
    assert.ok(isSolved(board), "hints did not finish the puzzle");
  }
});

// --- dead ends --------------------------------------------------------------

test("a wrong-but-legal entry is reported as a dead end, not a conflict", () => {
  const solution = fromString(REFERENCE.solution);
  const origin = fromString(REFERENCE.puzzle);
  const cell = firstEmpty(origin);
  const bad = wrongButLegal(origin, solution, cell)!;

  const board = origin.slice();
  board[cell] = bad;

  const edits: Edit[] = [{ cell, from: EMPTY, to: bad }];
  const hint = nextHint(board, solution, { origin, edits });

  assert.equal(hint.kind, "dead-end");
  assert.ok(hint.kind === "dead-end" && hint.deadEnd !== null);
  if (hint.kind === "dead-end" && hint.deadEnd) {
    assert.equal(hint.deadEnd.cell, cell);
    assert.equal(hint.deadEnd.digit, bad, "must blame the digit that is showing");
    assert.equal(hint.deadEnd.editIndex, 0, "must rewind exactly one entry");
  }
});

test("overwriting a cell blames the visible digit, not an earlier attempt", () => {
  const solution = fromString(REFERENCE.solution);
  const origin = fromString(REFERENCE.puzzle);
  const cell = firstEmpty(origin);

  const wrong: number[] = [];
  const used = new Set(PEERS[cell]!.map((p) => origin[p]!).filter((v) => v !== EMPTY));
  for (let d = 1; d <= 9 && wrong.length < 3; d += 1) {
    if (!used.has(d) && d !== solution[cell]) wrong.push(d);
  }
  assert.ok(wrong.length >= 2, "need at least two wrong-but-legal digits");

  const board = origin.slice();
  const edits: Edit[] = [];
  let previous = EMPTY;
  for (const d of wrong) {
    edits.push({ cell, from: previous, to: d });
    previous = d;
  }
  board[cell] = wrong[wrong.length - 1]!;

  const dead = findDeadEnd(origin, edits)!;
  assert.equal(dead.cell, cell);
  assert.equal(dead.digit, wrong[wrong.length - 1], "blames the digit on the board");
  assert.equal(dead.retried, true);
  assert.equal(dead.editIndex, 0, "all attempts at this cell must be rewound");
});

test("the rewind is minimal: undoing to editIndex recovers, one fewer does not", () => {
  const solution = fromString(REFERENCE.solution);
  const origin = fromString(REFERENCE.puzzle);

  // Two correct entries, then a wrong one, then another correct one.
  const edits: Edit[] = [];
  const board = origin.slice();
  const apply = (cell: number, digit: number): void => {
    edits.push({ cell, from: board[cell]!, to: digit });
    board[cell] = digit;
  };

  const empties = [...board.keys()].filter((i) => board[i] === EMPTY);
  apply(empties[0]!, solution[empties[0]!]!);
  apply(empties[1]!, solution[empties[1]!]!);
  const badCell = empties[2]!;
  apply(badCell, wrongButLegal(board, solution, badCell)!);

  const dead = findDeadEnd(origin, edits)!;
  assert.equal(dead.cell, badCell);
  assert.equal(dead.editIndex, 2, "should not blame the two correct entries");

  const rewound = origin.slice();
  for (let i = 0; i < dead.editIndex; i += 1) rewound[edits[i]!.cell] = edits[i]!.to;
  assert.ok(solve(rewound).solution !== null, "rewind must restore solvability");

  const oneFewer = origin.slice();
  for (let i = 0; i <= dead.editIndex; i += 1) oneFewer[edits[i]!.cell] = edits[i]!.to;
  assert.equal(solve(oneFewer).solution, null, "rewinding less must not recover");
});

test("erasing a bad entry clears the dead end", () => {
  const solution = fromString(REFERENCE.solution);
  const origin = fromString(REFERENCE.puzzle);
  const cell = firstEmpty(origin);
  const bad = wrongButLegal(origin, solution, cell)!;

  const edits: Edit[] = [
    { cell, from: EMPTY, to: bad },
    { cell, from: bad, to: EMPTY },
  ];
  assert.equal(findDeadEnd(origin, edits), null, "an erase revives the board");

  const board = origin.slice();
  const hint = nextHint(board, solution, { origin, edits });
  assert.notEqual(hint.kind, "dead-end");
});

test("an unsolvable puzzle blames the puzzle, not the player", () => {
  const origin = fromString(REFERENCE.puzzle);
  origin[1] = origin[0] = 5; // break it before any user entry
  const dead = findDeadEnd(origin, []);
  assert.ok(dead !== null && dead.editIndex === -1);
});

// --- boards with nothing to say ---------------------------------------------

test("an empty grid is ambiguous rather than revealed", () => {
  const hint = nextHint(new Uint8Array(81));
  assert.equal(hint.kind, "ambiguous");
});

test("a board with many solutions is never told an answer is forced", () => {
  // An under-constrained board can still have forced cells, so a deduction is
  // fine here. What must never happen is `reveal` -- stating one arbitrary
  // completion as though it were the answer.
  const board = fromString(REFERENCE.puzzle);
  for (let i = 0; i < 81 && countSolutions(board, 2) < 2; i += 1) board[i] = EMPTY;
  assert.ok(countSolutions(board, 2) > 1, "precondition");

  for (let step = 0; step < 60; step += 1) {
    const hint = nextHint(board);
    assert.notEqual(hint.kind, "reveal", "claimed a forced answer on an ambiguous board");
    if (hint.kind === "ambiguous" || hint.kind === "solved") return;
    if (hint.kind === "deduction") board[hint.deduction.cell] = hint.deduction.digit;
    else if (hint.kind === "refutation" && hint.determined) {
      board[hint.cell] = hint.remaining[0]!;
    } else break;
  }
});

// --- the three ways a player actually uses the button -----------------------

test("scenario: hint, hint, hint from the start -- always safe, always finishes", () => {
  for (const p of PUZZLES.slice(0, 20)) {
    const origin = fromString(p.puzzle);
    const solution = fromString(p.solution);
    const board = origin.slice();
    const edits: Edit[] = [];

    for (let step = 0; step < 200; step += 1) {
      const hint = nextHint(board, solution, { origin, edits });
      if (hint.kind === "solved") break;
      assert.ok(
        hint.kind !== "dead-end" && hint.kind !== "conflict",
        `hint-only play produced ${hint.kind}, which it must never do`,
      );

      let cell: number, digit: number;
      if (hint.kind === "deduction") {
        cell = hint.deduction.cell;
        digit = hint.deduction.digit;
      } else if (hint.kind === "refutation" && hint.determined) {
        cell = hint.cell;
        digit = hint.remaining[0]!;
      } else if (hint.kind === "reveal") {
        cell = hint.cell;
        digit = hint.digit;
      } else if (hint.kind === "refutation") {
        cell = hint.cell;
        digit = solution[hint.cell]!;
      } else {
        break;
      }
      assert.equal(solution[cell], digit, "hint-only play placed a wrong digit");
      edits.push({ cell, from: board[cell]!, to: digit });
      board[cell] = digit;
    }
    assert.ok(isSolved(board), `hint-only play did not finish ${p.label || "puzzle"}`);
  }
});

test("scenario: player is right so far, then asks -- gets a deduction, not an alarm", () => {
  for (const p of PUZZLES.slice(0, 15)) {
    const origin = fromString(p.puzzle);
    const solution = fromString(p.solution);
    const board = origin.slice();
    const edits: Edit[] = [];

    // Play five correct entries by hand.
    let placed = 0;
    for (let cell = 0; cell < 81 && placed < 5; cell += 1) {
      if (board[cell] !== EMPTY) continue;
      edits.push({ cell, from: EMPTY, to: solution[cell]! });
      board[cell] = solution[cell]!;
      placed += 1;
    }

    const hint = nextHint(board, solution, { origin, edits });
    assert.ok(
      hint.kind === "deduction" || hint.kind === "refutation" || hint.kind === "solved",
      `correct play produced ${hint.kind}`,
    );
    if (hint.kind === "deduction") {
      assert.equal(solution[hint.deduction.cell], hint.deduction.digit);
    }
  }
});

test("scenario: player is already wrong, then asks -- gets the dead end and a minimal rewind", () => {
  let exercised = 0;
  for (const p of PUZZLES.slice(0, 15)) {
    const origin = fromString(p.puzzle);
    const solution = fromString(p.solution);
    const board = origin.slice();
    const edits: Edit[] = [];

    // Three correct entries, then one wrong-but-legal one, then two more.
    let placed = 0;
    for (let cell = 0; cell < 81 && placed < 3; cell += 1) {
      if (board[cell] !== EMPTY) continue;
      edits.push({ cell, from: EMPTY, to: solution[cell]! });
      board[cell] = solution[cell]!;
      placed += 1;
    }
    const badCell = board.findIndex((v) => v === EMPTY);
    const bad = wrongButLegal(board, solution, badCell);
    if (bad === null) continue;
    edits.push({ cell: badCell, from: EMPTY, to: bad });
    board[badCell] = bad;

    const hint = nextHint(board, solution, { origin, edits });
    assert.equal(hint.kind, "dead-end", "a wrong board must be reported as such");
    if (hint.kind !== "dead-end" || hint.deadEnd === null) continue;

    assert.equal(hint.deadEnd.cell, badCell, "must blame the wrong entry");
    assert.equal(hint.deadEnd.digit, bad, "must blame the digit on the board");
    assert.equal(hint.deadEnd.editIndex, 3, "must not blame the correct entries");

    // Rewinding to editIndex must restore a solvable board.
    const rewound = origin.slice();
    for (let i = 0; i < hint.deadEnd.editIndex; i += 1) {
      rewound[edits[i]!.cell] = edits[i]!.to;
    }
    assert.ok(solve(rewound).solution !== null, "rewind must recover");
    assert.equal(nextHint(rewound, solution).kind !== "dead-end", true);
    exercised += 1;
  }
  assert.ok(exercised > 0, "no scenario exercised");
});

test("a conflict is reported before anything else", () => {
  const board = fromString(REFERENCE.puzzle);
  const cell = firstEmpty(board);
  const peerValue = PEERS[cell]!.map((p) => board[p]!).find((v) => v !== EMPTY)!;
  board[cell] = peerValue;
  const hint = nextHint(board);
  assert.equal(hint.kind, "conflict");
  assert.ok(hint.kind === "conflict" && hint.cells.includes(cell));
});

test("a solved board reports solved", () => {
  assert.equal(nextHint(fromString(REFERENCE.solution)).kind, "solved");
});

// --- hints never build on a dead board --------------------------------------

test("no deduction is offered on a board that cannot be completed", () => {
  const solution = fromString(REFERENCE.solution);
  const origin = fromString(REFERENCE.puzzle);
  let checked = 0;

  for (let cell = 0; cell < 81 && checked < 12; cell += 1) {
    if (origin[cell] !== EMPTY) continue;
    const bad = wrongButLegal(origin, solution, cell);
    if (bad === null) continue;
    const board = origin.slice();
    board[cell] = bad;
    const hint = nextHint(board, solution, {
      origin,
      edits: [{ cell, from: EMPTY, to: bad }],
    });
    assert.equal(
      hint.kind,
      "dead-end",
      `offered ${hint.kind} on a dead board at cell ${cell}`,
    );
    checked += 1;
  }
  assert.ok(checked > 0, "no scenario exercised");
});

// --- entry and editing edge cases -------------------------------------------

test("hint is idempotent: asking twice without acting gives the same answer", () => {
  for (const p of PUZZLES.slice(0, 10)) {
    const board = fromString(p.puzzle);
    const solution = fromString(p.solution);
    const a = nextHint(board, solution);
    const b = nextHint(board, solution);
    assert.deepEqual(a, b, "hint changed without the board changing");
  }
});

test("the last empty cell is deduced, never revealed", () => {
  const solution = fromString(REFERENCE.solution);
  const board = solution.slice();
  board[40] = EMPTY;
  const hint = nextHint(board, solution);
  assert.equal(hint.kind, "deduction");
  assert.ok(hint.kind === "deduction" && hint.deduction.cell === 40);
  assert.ok(hint.kind === "deduction" && hint.deduction.digit === solution[40]);
});

test("a complete but wrong board is a conflict, not a dead end", () => {
  // A full board that breaks no constraint *is* a solution, so any complete
  // wrong board must contain a duplicate somewhere.
  const board = fromString(REFERENCE.solution);
  board[0] = board[1]!;
  const hint = nextHint(board);
  assert.equal(hint.kind, "conflict");
});

test("two independent wrong entries rewind past both", () => {
  const origin = fromString(REFERENCE.puzzle);
  const solution = fromString(REFERENCE.solution);
  const board = origin.slice();
  const edits: Edit[] = [];

  const wrongCells: number[] = [];
  for (let cell = 0; cell < 81 && wrongCells.length < 2; cell += 1) {
    if (board[cell] !== EMPTY) continue;
    const bad = wrongButLegal(board, solution, cell);
    if (bad === null) continue;
    edits.push({ cell, from: EMPTY, to: bad });
    board[cell] = bad;
    wrongCells.push(cell);
  }
  assert.equal(wrongCells.length, 2, "precondition");

  const dead = findDeadEnd(origin, edits)!;
  assert.equal(dead.editIndex, 0, "must rewind past the earlier mistake too");

  const rewound = origin.slice();
  for (let i = 0; i < dead.editIndex; i += 1) rewound[edits[i]!.cell] = edits[i]!.to;
  assert.ok(solve(rewound).solution !== null);
});

test("a wrong entry followed by correct ones still blames the wrong one", () => {
  const origin = fromString(REFERENCE.puzzle);
  const solution = fromString(REFERENCE.solution);
  const board = origin.slice();
  const edits: Edit[] = [];

  const badCell = board.findIndex((v) => v === EMPTY);
  const bad = wrongButLegal(board, solution, badCell)!;
  edits.push({ cell: badCell, from: EMPTY, to: bad });
  board[badCell] = bad;

  let placed = 0;
  for (let cell = 0; cell < 81 && placed < 4; cell += 1) {
    if (board[cell] !== EMPTY) continue;
    edits.push({ cell, from: EMPTY, to: solution[cell]! });
    board[cell] = solution[cell]!;
    placed += 1;
  }

  const dead = findDeadEnd(origin, edits)!;
  assert.equal(dead.cell, badCell);
  assert.equal(dead.editIndex, 0, "the correct entries after it must go too");
});

test("correcting a wrong entry in place clears the dead end", () => {
  const origin = fromString(REFERENCE.puzzle);
  const solution = fromString(REFERENCE.solution);
  const cell = origin.findIndex((v) => v === EMPTY);
  const bad = wrongButLegal(origin, solution, cell)!;
  const edits: Edit[] = [
    { cell, from: EMPTY, to: bad },
    { cell, from: bad, to: solution[cell]! },
  ];
  assert.equal(findDeadEnd(origin, edits), null);
});

test("an empty edit list on a good board reports nothing", () => {
  const origin = fromString(REFERENCE.puzzle);
  assert.equal(findDeadEnd(origin, []), null);
});

// --- solver invariants the hints depend on ----------------------------------

test("every library puzzle has exactly one solution", () => {
  for (const p of PUZZLES) {
    assert.equal(countSolutions(fromString(p.puzzle), 2), 1, p.label || p.puzzle);
  }
});

test("countSolutions stops at the limit rather than enumerating", () => {
  assert.equal(countSolutions(new Uint8Array(81), 2), 2);
  assert.equal(countSolutions(fromString(REFERENCE.solution), 2), 1);
});

test("an inconsistent board has no solutions", () => {
  const board = fromString(REFERENCE.puzzle);
  const cell = board.findIndex((v) => v === EMPTY);
  const peer = PEERS[cell]!.find((p) => board[p] !== EMPTY)!;
  board[cell] = board[peer]!;
  assert.equal(countSolutions(board, 2), 0);
});

test("TypeScript node counts match the Python reference exactly", () => {
  // puzzles.json carries node counts produced by the Python solver. Matching
  // them proves both searches make the same decisions in the same order, which
  // is a far stronger check than merely agreeing on the answer.
  for (const p of PUZZLES) {
    const { solution, stats } = solve(fromString(p.puzzle));
    assert.notEqual(solution, null);
    assert.equal(stats.nodes, p.nodes, `node mismatch on ${p.label || p.puzzle}`);
  }
});

test("refutations never rule out the correct digit", () => {
  let checked = 0;
  for (const p of PUZZLES.filter((x) => x.nodes > 0)) {
    const board = fromString(p.puzzle);
    const solution = fromString(p.solution);
    for (let step = 0; step < 200; step += 1) {
      const hint = nextHint(board, solution);
      if (hint.kind === "solved") break;
      if (hint.kind === "refutation") {
        for (const r of hint.refuted) {
          assert.notEqual(solution[hint.cell], r.digit, "refuted the answer");
        }
        checked += 1;
        board[hint.cell] = hint.determined ? hint.remaining[0]! : solution[hint.cell]!;
      } else if (hint.kind === "deduction") {
        board[hint.deduction.cell] = hint.deduction.digit;
      } else break;
    }
  }
  assert.ok(checked > 0, "no refutation exercised");
});

/**
 * Hints, tiered by how much they can actually justify.
 *
 * The rule this module follows: **never claim to prove something it cannot
 * explain.** A hint that reveals a digit without a reason teaches nothing, and
 * a hint whose proof is forty steps deep is not a proof a person can follow.
 * So each tier states exactly what kind of evidence it has.
 *
 *   conflict     you have entered something that breaks a constraint
 *   deduction    a rule fires: naked single or hidden single, with its reason
 *   refutation   nothing follows directly, but a candidate can be *ruled out*
 *                because assuming it produces a contradiction
 *   reveal       last resort: the answer, labelled as an answer and not a proof
 *
 * The refutation tier is what happens when the solver would backtrack. A failed
 * branch is a real deduction -- proof by contradiction -- and it is the honest
 * thing to show at exactly the point where inference alone has run out.
 */

import { EMPTY, findConflicts, isComplete, type Board } from "./board";
import {
  bit,
  countSolutions,
  initialDomains,
  maskToDigits,
  onlyDigit,
  popcount,
  propagate,
  solve,
  type Domains,
} from "./solve";
import { BOXES, COLS, N, N_CELLS, PEERS, ROWS } from "./units";

export type UnitKind = "row" | "column" | "box";

export interface Deduction {
  kind: "naked-single" | "hidden-single";
  cell: number;
  digit: number;
  /** For a hidden single, the unit that justifies it. */
  unit?: { kind: UnitKind; index: number; cells: number[] };
  /** For a naked single, the peers that eliminated everything else. */
  because?: number[];
}

/** How hard it was to rule a candidate out, which decides if it is explainable. */
export type RefutationDepth = "propagation" | "search";

export interface Refutation {
  digit: number;
  depth: RefutationDepth;
  /** The cell whose candidates ran out, when propagation found it directly. */
  contradictionAt: number | null;
}

export interface Edit {
  cell: number;
  from: number;
  to: number;
}

/** Where a board stopped being solvable, and which edit did it. */
export interface DeadEnd {
  /** Index into the edit list, or -1 when the puzzle itself was unsolvable. */
  editIndex: number;
  cell: number;
  /** The digit currently showing in that cell. */
  digit: number;
  /** True when the cell was tried more than once and every attempt was wrong. */
  retried?: boolean;
}

export type Hint =
  | { kind: "solved" }
  | { kind: "conflict"; cells: number[] }
  | { kind: "unsolvable" }
  | { kind: "dead-end"; deadEnd: DeadEnd | null }
  | { kind: "deduction"; deduction: Deduction }
  | {
      kind: "refutation";
      cell: number;
      refuted: Refutation[];
      remaining: number[];
      /** True when only one candidate survives, so the cell is now determined. */
      determined: boolean;
    }
  | { kind: "reveal"; cell: number; digit: number }
  | { kind: "ambiguous"; solutions: number };

function unitOf(index: number): { kind: UnitKind; index: number; cells: number[] } {
  if (index < N) return { kind: "row", index, cells: ROWS[index]! };
  if (index < 2 * N) return { kind: "column", index: index - N, cells: COLS[index - N]! };
  return { kind: "box", index: index - 2 * N, cells: BOXES[index - 2 * N]! };
}

/**
 * The single next thing that follows with certainty, or null if nothing does.
 *
 * Deliberately *one* step, and deliberately not run to a fixpoint: a hint
 * should be the next move a person could make, not the twenty moves after it.
 * Naked singles are checked first because they are the simpler technique to
 * explain.
 */
export function nextDeduction(board: Board): Deduction | null {
  const domains = initialDomains(board);
  if (domains === null) return null;

  for (let cell = 0; cell < N_CELLS; cell += 1) {
    if (board[cell] !== EMPTY) continue;
    if (popcount(domains[cell]!) === 1) {
      const digit = onlyDigit(domains[cell]!);
      const because = PEERS[cell]!.filter((peer) => board[peer] !== EMPTY);
      return { kind: "naked-single", cell, digit, because };
    }
  }

  for (let u = 0; u < 27; u += 1) {
    const unit = unitOf(u);
    for (let digit = 1; digit <= N; digit += 1) {
      const mask = bit(digit);
      // Already placed in this unit; nothing to deduce.
      if (unit.cells.some((cell) => board[cell] === digit)) continue;
      const homes = unit.cells.filter(
        (cell) => board[cell] === EMPTY && (domains[cell]! & mask) !== 0,
      );
      if (homes.length === 1) {
        return { kind: "hidden-single", cell: homes[0]!, digit, unit };
      }
    }
  }

  return null;
}

/**
 * Try to rule a candidate out by assuming it and looking for a contradiction.
 *
 * Returns null when the assumption survives. `depth` records how the
 * contradiction was found, because that determines whether the result can be
 * explained to a person: `propagation` means the clash follows directly from
 * the assumption, while `search` means it needed guessing of its own and is
 * only honestly described as "the solver checked".
 */
export function refuteCandidate(
  board: Board,
  cell: number,
  digit: number,
): Refutation | null {
  const domains = initialDomains(board);
  if (domains === null) return null;

  const branch: Domains = domains.slice();
  branch[cell] = bit(digit);

  // First: does propagation alone kill it? That is the explainable case.
  const probe: Domains = branch.slice();
  let wipedOut: number | null = null;
  if (!propagate(probe)) {
    for (let c = 0; c < N_CELLS; c += 1) {
      if (probe[c] === 0) {
        wipedOut = c;
        break;
      }
    }
    return { digit, depth: "propagation", contradictionAt: wipedOut };
  }

  // Otherwise fall back to full search on the hypothetical board.
  const hypothetical = board.slice();
  hypothetical[cell] = digit;
  const { solution } = solve(hypothetical);
  if (solution === null) {
    return { digit, depth: "search", contradictionAt: null };
  }
  return null;
}

/**
 * The next hint for a board, at the strongest tier that can be justified.
 *
 * `solution` is optional and only used for the final reveal tier; when it is
 * absent the solver computes one.
 */
/**
 * Find the smallest set of recent edits that has to be undone to make the
 * board solvable again, and name the one that caused it.
 *
 * Scans **backwards**, reverting edits until the board recovers. A forward
 * scan is wrong: it reports the first edit that ever made the board
 * unsolvable, but a later edit can change that same cell again, so it blames a
 * value the user has already replaced and asks them to undo more than they
 * need to. Reverting from the end finds the actual culprit and the minimal
 * rewind.
 */
export function findDeadEnd(origin: Board, edits: Edit[]): DeadEnd | null {
  const replay = origin.slice();
  for (const edit of edits) replay[edit.cell] = edit.to;

  // Nothing to diagnose if the board is fine as it stands.
  if (solve(replay).solution !== null) return null;

  // Blame what is *on the board now*, not a value the user has overwritten.
  // Reading the digit mid-rewind reported the earliest attempt at that cell,
  // naming a digit no longer visible anywhere.
  const onBoard = replay.slice();

  for (let i = edits.length - 1; i >= 0; i -= 1) {
    const edit = edits[i]!;
    replay[edit.cell] = edit.from;
    if (solve(replay).solution !== null) {
      return {
        editIndex: i,
        cell: edit.cell,
        digit: onBoard[edit.cell]!,
        /** True when this cell was tried several times, all of them wrong. */
        retried: onBoard[edit.cell] !== edit.to,
      };
    }
  }

  // Back at the original board and still unsolvable: the puzzle itself is.
  return { editIndex: -1, cell: -1, digit: 0 };
}

export interface HintContext {
  /** The puzzle as loaded, before any user entry. */
  origin: Board;
  /** The user's applied edits, oldest first. */
  edits: Edit[];
}

export function nextHint(
  board: Board,
  solution?: Board,
  context?: HintContext,
): Hint {
  const conflicts = findConflicts(board);
  if (conflicts.length > 0) {
    return { kind: "conflict", cells: [...new Set(conflicts.flat())] };
  }
  if (isComplete(board)) return { kind: "solved" };

  // A board can break no rule and still be dead: a digit that is legal now but
  // simply is not the answer removes the solution without any conflict to see.
  // Check before deducing, or the hint cheerfully derives valid consequences
  // of a false premise.
  if (solve(board).solution === null) {
    const deadEnd =
      context === undefined ? null : findDeadEnd(context.origin, context.edits);
    return { kind: "dead-end", deadEnd };
  }

  const deduction = nextDeduction(board);
  if (deduction !== null) return { kind: "deduction", deduction };

  // Inference has run out -- this is where the solver would branch. Rather
  // than guessing at the user, try to rule candidates out by contradiction.
  const domains = initialDomains(board);
  if (domains === null) return { kind: "unsolvable" };

  let target = -1;
  let fewest = N + 1;
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    if (board[cell] !== EMPTY) continue;
    const size = popcount(domains[cell]!);
    if (size > 1 && size < fewest) {
      fewest = size;
      target = cell;
    }
  }

  if (target >= 0) {
    const candidates = maskToDigits(domains[target]!);
    const refuted: Refutation[] = [];
    for (const digit of candidates) {
      const result = refuteCandidate(board, target, digit);
      if (result !== null) refuted.push(result);
    }
    if (refuted.length > 0) {
      const ruledOut = new Set(refuted.map((r) => r.digit));
      const remaining = candidates.filter((d) => !ruledOut.has(d));
      return {
        kind: "refutation",
        cell: target,
        refuted,
        remaining,
        determined: remaining.length === 1,
      };
    }
  }

  // An under-constrained board has nothing to deduce: many completions are
  // valid, so "the answer" would just be one arbitrary solution among them.
  const count = countSolutions(board, 2);
  if (count > 1) return { kind: "ambiguous", solutions: count };

  // Nothing could be ruled out -- fall back to stating the answer plainly.
  const answer = solution ?? solve(board).solution;
  if (answer === null) return { kind: "unsolvable" };
  const cell = target >= 0 ? target : board.findIndex((v) => v === EMPTY);
  if (cell < 0) return { kind: "solved" };
  return { kind: "reveal", cell, digit: answer[cell]! };
}

const UNIT_LABEL = (unit: { kind: UnitKind; index: number }): string =>
  `${unit.kind} ${unit.index + 1}`;

export const cellName = (cell: number): string =>
  `R${Math.floor(cell / N) + 1}C${(cell % N) + 1}`;

/** Human-readable hint text, and the cells worth highlighting alongside it. */
export function describeHint(hint: Hint): { title: string; body: string; cells: number[] } {
  switch (hint.kind) {
    case "solved":
      return { title: "Solved", body: "Every cell is filled and nothing conflicts.", cells: [] };

    case "conflict":
      return {
        title: "There is a conflict",
        body:
          "Two highlighted cells share a row, column or box and hold the same " +
          "digit. Fix that before asking for another hint -- no deduction is " +
          "valid on a board that already breaks a rule.",
        cells: hint.cells,
      };

    case "unsolvable":
      return {
        title: "No solution",
        body: "This board cannot be completed.",
        cells: [],
      };

    case "dead-end": {
      const d = hint.deadEnd;
      if (d === null) {
        return {
          title: "Dead end",
          body:
            "Nothing here breaks a rule, but the puzzle can no longer be " +
            "completed — an earlier entry must be wrong. Undo until it can.",
          cells: [],
        };
      }
      if (d.editIndex < 0) {
        return {
          title: "This puzzle has no solution",
          body: "The board as loaded cannot be completed, so nothing you entered is at fault.",
          cells: [],
        };
      }
      const retriedNote = d.retried
        ? ` You have tried more than one digit there, and none of them can be ` +
          `right, so the rewind clears them all.`
        : "";
      return {
        title: `Dead end — ${cellName(d.cell)} = ${d.digit} cannot be right`,
        body:
          `Nothing on the board breaks a rule, so there is no conflict to ` +
          `see. But ${d.digit} at ${cellName(d.cell)} is not the answer, and ` +
          `while it is there the puzzle cannot be completed.${retriedNote}\n\n` +
          `This is what backtracking is: undo to before that entry and take ` +
          `a different branch. The solver does the same thing, just faster.`,
        cells: [d.cell],
      };
    }

    case "deduction": {
      const d = hint.deduction;
      if (d.kind === "naked-single") {
        return {
          title: `Naked single — ${cellName(d.cell)} must be ${d.digit}`,
          body:
            `Every other digit already appears among the 20 cells that share a ` +
            `row, column or box with ${cellName(d.cell)}, so ${d.digit} is the ` +
            `only one left that fits.`,
          cells: [d.cell],
        };
      }
      const label = d.unit ? UNIT_LABEL(d.unit) : "unit";
      return {
        title: `Hidden single — ${cellName(d.cell)} must be ${d.digit}`,
        body:
          `Look at ${label}. The digit ${d.digit} has to go somewhere in it, ` +
          `and ${cellName(d.cell)} is the only cell still able to take it — ` +
          `even though that cell has other candidates of its own.`,
        cells: d.unit ? d.unit.cells : [d.cell],
      };
    }

    case "refutation": {
      const byProof = hint.refuted.filter((r) => r.depth === "propagation");
      const bySearch = hint.refuted.filter((r) => r.depth === "search");
      const parts: string[] = [
        `No rule fires anywhere on this board — inference has run out, and ` +
          `this is exactly where the solver starts guessing.`,
        "",
        `But a guess can still be checked. At ${cellName(hint.cell)}:`,
      ];
      for (const r of byProof) {
        const where = r.contradictionAt === null ? "" : ` at ${cellName(r.contradictionAt)}`;
        parts.push(
          `• ${r.digit} is impossible — assume it and a cell runs out of ` +
            `candidates${where}.`,
        );
      }
      for (const r of bySearch) {
        parts.push(
          `• ${r.digit} is impossible, but only after further guessing — too ` +
            `deep to follow by hand.`,
        );
      }
      if (hint.determined) {
        parts.push("", `That leaves ${hint.remaining[0]}, so it must go there.`);
      } else if (hint.remaining.length > 0) {
        parts.push("", `Still possible: ${hint.remaining.join(", ")}.`);
      }
      return {
        title: hint.determined
          ? `By contradiction — ${cellName(hint.cell)} must be ${hint.remaining[0]}`
          : `By contradiction — ruling candidates out at ${cellName(hint.cell)}`,
        body: parts.join("\n"),
        cells: [hint.cell],
      };
    }

    case "ambiguous":
      return {
        title: "Nothing is forced here",
        body:
          "This board has more than one valid completion, so no digit is " +
          "determined and there is nothing to deduce. Load a puzzle, or add " +
          "more clues, and hints will have something to work with.",
        cells: [],
      };

    case "reveal":
      return {
        title: `${cellName(hint.cell)} is ${hint.digit}`,
        body:
          "No technique proves this and no candidate could be ruled out, so " +
          "this is the answer rather than a deduction.",
        cells: [hint.cell],
      };
  }
}

/**
 * Propagation and search, ported from `src/gridmind/propagate.py` and
 * `src/gridmind/solvers/backtracking.py`.
 *
 * The one addition over the Python version is the **event log**. Every
 * inference and every branch can be recorded, which is what makes Lessons 46
 * and 47 possible: you replay the log to animate the solver's reasoning
 * instead of just showing the answer.
 */

import { EMPTY, type Board } from "./board";
import { N, N_CELLS, PEERS, UNITS } from "./units";

export const FULL_MASK = (1 << N) - 1;

export type Domains = Int16Array;

export const bit = (digit: number): number => 1 << (digit - 1);
export const popcount = (mask: number): number => {
  let count = 0;
  let m = mask;
  while (m) {
    m &= m - 1;
    count += 1;
  }
  return count;
};
export const onlyDigit = (mask: number): number => 32 - Math.clz32(mask);
export const maskToDigits = (mask: number): number[] => {
  const digits: number[] = [];
  for (let d = 1; d <= N; d += 1) if (mask & bit(d)) digits.push(d);
  return digits;
};

export type SolveEvent =
  | { kind: "given"; cell: number; digit: number }
  | { kind: "naked-single"; cell: number; digit: number }
  | { kind: "hidden-single"; cell: number; digit: number; unit: number }
  | { kind: "branch"; cell: number; digit: number; candidates: number[] }
  | { kind: "backtrack"; cell: number; digit: number }
  | { kind: "contradiction"; cell: number }
  | { kind: "solved" };

export interface SearchStats {
  /** When false, counters still update but no events are captured. */
  record: boolean;
  nodes: number;
  backtracks: number;
  propagations: number;
  /** Solutions found. Only `countSolutions` looks for more than one. */
  solutions: number;
  events: SolveEvent[];
  ms: number;
}

const pushEvent = (stats: SearchStats | undefined, event: SolveEvent): void => {
  if (stats?.record) stats.events.push(event);
};

export const emptyStats = (record = false): SearchStats => ({
  record,
  nodes: 0,
  backtracks: 0,
  propagations: 0,
  solutions: 0,
  events: [],
  ms: 0,
});

export function initialDomains(
  board: Board,
  stats?: SearchStats,
): Domains | null {
  const domains = new Int16Array(N_CELLS).fill(FULL_MASK);
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    const value = board[cell]!;
    if (value === EMPTY) continue;
    if (!(domains[cell]! & bit(value))) return null;
    domains[cell] = bit(value);
    pushEvent(stats, { kind: "given", cell, digit: value });
    for (const peer of PEERS[cell]!) {
      domains[peer]! &= ~bit(value);
      if (domains[peer] === 0) {
        pushEvent(stats, { kind: "contradiction", cell: peer });
        return null;
      }
    }
  }
  return domains;
}

export function nakedSingles(domains: Domains, stats?: SearchStats): boolean {
  const queue: number[] = [];
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    if (popcount(domains[cell]!) === 1) queue.push(cell);
  }
  while (queue.length > 0) {
    const cell = queue.pop()!;
    const mask = domains[cell]!;
    if (popcount(mask) !== 1) continue;
    for (const peer of PEERS[cell]!) {
      if (domains[peer]! & mask) {
        domains[peer]! &= ~mask;
        if (domains[peer] === 0) {
          pushEvent(stats, { kind: "contradiction", cell: peer });
          return false;
        }
        if (popcount(domains[peer]!) === 1) {
          pushEvent(stats, {
            kind: "naked-single",
            cell: peer,
            digit: onlyDigit(domains[peer]!),
          });
          queue.push(peer);
        }
      }
    }
  }
  return true;
}

export function hiddenSingles(domains: Domains, stats?: SearchStats): boolean {
  let changed = true;
  while (changed) {
    changed = false;
    for (let u = 0; u < UNITS.length; u += 1) {
      const unit = UNITS[u]!;
      for (let digit = 1; digit <= N; digit += 1) {
        const mask = bit(digit);
        const homes = unit.filter((cell) => domains[cell]! & mask);
        if (homes.length === 0) return false;
        if (homes.length === 1) {
          const cell = homes[0]!;
          if (domains[cell] !== mask) {
            domains[cell] = mask;
            changed = true;
            pushEvent(stats, {
              kind: "hidden-single",
              cell,
              digit,
              unit: u,
            });
            if (!nakedSingles(domains, stats)) return false;
          }
        }
      }
    }
  }
  return true;
}

export function propagate(domains: Domains, stats?: SearchStats): boolean {
  if (stats) stats.propagations += 1;
  if (!nakedSingles(domains, stats)) return false;
  return hiddenSingles(domains, stats);
}

/** MRV: branch on the cell with the fewest candidates. -1 when all decided. */
export function mrv(domains: Domains): number {
  let bestCell = -1;
  let bestSize = N + 1;
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    const size = popcount(domains[cell]!);
    if (size > 1 && size < bestSize) {
      bestSize = size;
      bestCell = cell;
      if (size === 2) break;
    }
  }
  return bestCell;
}

function search(
  domains: Domains,
  stats: SearchStats,
  out: { result: Domains | null },
): boolean {
  const cell = mrv(domains);
  if (cell < 0) {
    out.result = domains.slice();
    pushEvent(stats, { kind: "solved" });
    return true;
  }

  stats.nodes += 1;
  const candidates = maskToDigits(domains[cell]!);
  for (const digit of candidates) {
    pushEvent(stats, { kind: "branch", cell, digit, candidates });
    const branch = domains.slice();
    branch[cell] = bit(digit);
    if (propagate(branch, stats)) {
      if (search(branch, stats, out)) return true;
    }
    stats.backtracks += 1;
    pushEvent(stats, { kind: "backtrack", cell, digit });
  }
  return false;
}

export interface SolveResult {
  solution: Board | null;
  stats: SearchStats;
}

export function solve(board: Board, record = false): SolveResult {
  const stats = emptyStats(record);
  const started = performance.now();

  const domains = initialDomains(board, stats);
  if (domains === null) {
    stats.ms = performance.now() - started;
    return { solution: null, stats };
  }
  if (!propagate(domains, stats)) {
    stats.ms = performance.now() - started;
    return { solution: null, stats };
  }

  const out: { result: Domains | null } = { result: null };
  search(domains, stats, out);
  stats.ms = performance.now() - started;

  if (out.result === null) return { solution: null, stats };
  const solution = new Uint8Array(N_CELLS);
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    solution[cell] = onlyDigit(out.result[cell]!);
  }
  return { solution, stats };
}

/**
 * Count solutions, stopping at `limit`.
 *
 * Distinguishing "exactly one solution" from "many" is what tells a hint
 * whether anything is actually forced. Checking for a *second* solution is far
 * cheaper than enumerating them all.
 */
export function countSolutions(board: Board, limit = 2): number {
  const stats = emptyStats();
  const domains = initialDomains(board);
  if (domains === null) return 0;
  if (!propagate(domains, stats)) return 0;
  const out: { result: Domains | null } = { result: null };
  searchCounting(domains, stats, out, limit);
  return stats.solutions;
}

function searchCounting(
  domains: Domains,
  stats: SearchStats,
  out: { result: Domains | null },
  limit: number,
): boolean {
  const cell = mrv(domains);
  if (cell < 0) {
    stats.solutions += 1;
    out.result = domains.slice();
    return stats.solutions >= limit;
  }
  stats.nodes += 1;
  for (const digit of maskToDigits(domains[cell]!)) {
    const branch = domains.slice();
    branch[cell] = bit(digit);
    if (propagate(branch, stats)) {
      if (searchCounting(branch, stats, out, limit)) return true;
    }
  }
  return false;
}

/** Candidate sets after propagation only — what Lesson 47 renders. */
export function candidatesAfterPropagation(board: Board): Domains | null {
  const domains = initialDomains(board);
  if (domains === null) return null;
  return propagate(domains) ? domains : null;
}

/**
 * Grid structure: units, peers, and the constraint graph.
 *
 * This is the TypeScript twin of `src/gridmind/units.py`. Keeping the two in
 * step is deliberate — Lesson 45 asks you to port the solver and check that
 * both implementations agree node-for-node on the same puzzles.
 */

export const N = 9;
export const BOX = 3;
export const N_CELLS = N * N;

export const rcToIndex = (row: number, col: number): number => row * N + col;
export const indexToRc = (index: number): [number, number] => [
  Math.floor(index / N),
  index % N,
];

export const boxOf = (index: number): number => {
  const [row, col] = indexToRc(index);
  return Math.floor(row / BOX) * BOX + Math.floor(col / BOX);
};

const buildRows = (): number[][] =>
  Array.from({ length: N }, (_, r) =>
    Array.from({ length: N }, (_, c) => rcToIndex(r, c)),
  );

const buildCols = (): number[][] =>
  Array.from({ length: N }, (_, c) =>
    Array.from({ length: N }, (_, r) => rcToIndex(r, c)),
  );

const buildBoxes = (): number[][] => {
  const boxes: number[][] = Array.from({ length: N }, () => []);
  for (let cell = 0; cell < N_CELLS; cell += 1) boxes[boxOf(cell)]!.push(cell);
  return boxes;
};

export const ROWS = buildRows();
export const COLS = buildCols();
export const BOXES = buildBoxes();

/** All 27 units: nine rows, nine columns, nine boxes. */
export const UNITS: number[][] = [...ROWS, ...COLS, ...BOXES];

/** The three units each cell belongs to. */
export const UNITS_OF: number[][][] = Array.from({ length: N_CELLS }, (_, cell) =>
  UNITS.filter((unit) => unit.includes(cell)),
);

/** The 20 cells that constrain each cell. */
export const PEERS: number[][] = Array.from({ length: N_CELLS }, (_, cell) => {
  const peers = new Set<number>();
  for (const unit of UNITS_OF[cell]!) {
    for (const other of unit) if (other !== cell) peers.add(other);
  }
  return [...peers].sort((a, b) => a - b);
});

/** Undirected constraint graph, each edge once with a < b. 810 of them. */
export const EDGES: Array<[number, number]> = (() => {
  const edges: Array<[number, number]> = [];
  for (let a = 0; a < N_CELLS; a += 1) {
    for (const b of PEERS[a]!) if (a < b) edges.push([a, b]);
  }
  return edges;
})();

